package sandbox

import (
	"fmt"
	"testing"
)

func TestReverse(t *testing.T) {
	testCases := []struct {
		input    string
		expected string
	}{
		{"", ""},
		{"a", "a"},
		{"ab", "ba"},
		{"hello", "olleh"},
		{"世界", "界世"},
		{"Go语言", "语言Go"},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Reverse(%q)", tc.input), func(t *testing.T) {
			result := Reverse(tc.input)
			if result != tc.expected {
				t.Errorf("Reverse(%q) = %q; want %q", tc.input, result, tc.expected)
			}
		})
	}
}

// Reverse reverses s by runes (Unicode-safe).
func Reverse(s string) string {
	runes := []rune(s)
	for i, j := 0, len(runes)-1; i < j; i, j = i+1, j-1 {
		runes[i], runes[j] = runes[j], runes[i]
	}
	return string(runes)
}

package sandbox

import (
	"fmt"
	"reflect"
	"strings"
	"testing"
)

// WordCount returns a map of words to their counts in the given string.
func WordCount(s string) map[string]int {
	words := strings.Fields(s)
	wordCount := make(map[string]int)
	for _, word := range words {
		wordCount[word]++
	}
	return wordCount
}

// TestWordCount tests the WordCount function with various inputs.
func TestWordCount(t *testing.T) {
	testCases := []struct {
		input    string
		expected map[string]int
	}{
		{"", map[string]int{}},
		{"hello", map[string]int{"hello": 1}},
		{"hello world", map[string]int{"hello": 1, "world": 1}},
		{"hello hello", map[string]int{"hello": 2}},
		{"hello world hello", map[string]int{"hello": 2, "world": 1}},
		{"  hello   world  ", map[string]int{"hello": 1, "world": 1}},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result := WordCount(tc.input)
			if !reflect.DeepEqual(result, tc.expected) {
				t.Errorf("WordCount(%q) = %v; want %v", tc.input, result, tc.expected)
			}
		})
	}
}

