import (
	"errors"
	"fmt"
	"strconv"
	"testing"
)

var ErrBadPort = errors.New("bad port")

func ParsePort(s string) (int, error) {
	port, err := strconv.Atoi(s)
	if err != nil {
		return 0, fmt.Errorf("%w: %s", ErrBadPort, err)
	}
	if port < 1 || port > 65535 {
		return 0, fmt.Errorf("%w: port out of range", ErrBadPort)
	}
	return port, nil
}

func TestParsePort(t *testing.T) {
	testCases := []struct {
		input    string
		expected int
		err      error
	}{
		{"8080", 8080, nil},
		{"65535", 65535, nil},
		{"0", 0, fmt.Errorf("%w: port out of range", ErrBadPort)},
		{"65536", 0, fmt.Errorf("%w: port out of range", ErrBadPort)},
		{"abc", 0, fmt.Errorf("%w: strconv.Atoi: invalid syntax", ErrBadPort)},
		{"-1", 0, fmt.Errorf("%w: port out of range", ErrBadPort)},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result, err := ParsePort(tc.input)
			if !errors.Is(err, tc.err) {
				t.Errorf("Expected error: %v, got: %v", tc.err, err)
			}
			if result != tc.expected {
				t.Errorf("Expected result: %d, got: %d", tc.expected, result)
			}
		})
	}
}

package sandbox

import (
	"sync"
	"testing"
)

type Counter struct {
	mu     sync.Mutex
	counts map[string]int
}

func (c *Counter) Inc(key string) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.counts[key]++
}

func (c *Counter) Get(key string) int {
	c.mu.Lock()
	defer c.mu.Unlock()
	return c.counts[key]
}

func TestCounter(t *testing.T) {
	c := &Counter{counts: make(map[string]int)}

	// Test Inc and Get
	c.Inc("testKey")
	if c.Get("testKey") != 1 {
		t.Errorf("Expected count for 'testKey' to be 1, got %d", c.Get("testKey"))
	}

	c.Inc("testKey")
	if c.Get("testKey") != 2 {
		t.Errorf("Expected count for 'testKey' to be 2, got %d", c.Get("testKey"))
	}

	// Test concurrent access
	var wg sync.WaitGroup
	for i := 0; i < 100; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			c.Inc("concurrentKey")
		}()
	}
	wg.Wait()
	if c.Get("concurrentKey") != 100 {
		t.Errorf("Expected count for 'concurrentKey' to be 100, got %d", c.Get("concurrentKey"))
	}
}

