	tests := []struct {
		name     string
		point    Point
		expected string
	}{
		{"Positive Coordinates", Point{X: 1, Y: 2}, `{"x":1,"y":2}`},
		{"Negative Coordinates", Point{X: -1, Y: -2}, `{"x":-1,"y":-2}`},
		{"Zero Coordinates", Point{X: 0, Y: 0}, `{"x":0,"y":0}`},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			result, err := Encode(tt.point)
			if err != nil {
				t.Errorf("Encode() error = %v", err)
				return
			}
			if result != tt.expected {
				t.Errorf("Encode() = %v, want %v", result, tt.expected)
			}
		})
	}
}

