// SortByLen sorts the input slice of strings in place by ascending string length.
func SortByLen(ss []string) {
	sort.SliceStable(ss, func(i, j int) bool {
		return len(ss[i]) < len(ss[j])
	})
}

// TestSortByLen tests the SortByLen function with various test cases.
func TestSortByLen(t *testing.T) {
	testCases := []struct {
		input    []string
		expected []string
	}{
		{[]string{"apple", "banana", "cherry"}, []string{"apple", "banana", "cherry"}},
		{[]string{"banana", "apple", "cherry"}, []string{"apple", "banana", "cherry"}},
		{[]string{"cherry", "banana", "apple"}, []string{"apple", "banana", "cherry"}},
		{[]string{"", "a", "bb", "ccc"}, []string{"", "a", "bb", "ccc"}},
		{[]string{"ccc", "bb", "a", ""}, []string{"", "a", "bb", "ccc"}},
		{[]string{"a", "b", "c", "d", "e"}, []string{"a", "b", "c", "d", "e"}},
		{[]string{"e", "d", "c", "b", "a"}, []string{"a", "b", "c", "d", "e"}},
		{[]string{"apple", "apple", "apple"}, []string{"apple", "apple", "apple"}},
		{[]string{"", "", ""}, []string{"", "", ""}},
		{[]string{}, []string{}},
	}

	for _, tc := range testCases {
		SortByLen(tc.input)
		if !equal(tc.input, tc.expected) {
			t.Errorf("SortByLen(%v) = %v; want %v", tc.input, tc.input, tc.expected)
		}
	}
}

// equal checks if two slices of strings are equal.
func equal(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

