func TestMax(t *testing.T) {
	testCases := []struct {
		name     string
		input    []any
		expected any
	}{
		{"empty int slice", []any{}, 0},
		{"empty int64 slice", []any{}, int64(0)},
		{"empty float64 slice", []any{}, float64(0)},
		{"int slice with one element", []any{5}, 5},
		{"int slice with multiple elements", []any{1, 3, 2, 5, 4}, 5},
		{"int64 slice with one element", []any{int64(5)}, int64(5)},
		{"int64 slice with multiple elements", []any{int64(1), int64(3), int64(2), int64(5), int64(4)}, int64(5)},
		{"float64 slice with one element", []any{float64(5)}, float64(5)},
		{"float64 slice with multiple elements", []any{float64(1), float64(3), float64(2), float64(5), float64(4)}, float64(5)},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			var max any
			var ok bool
			switch tc.expected.(type) {
			case int:
				max, ok = Max[int](tc.input.([]int)...)
			case int64:
				max, ok = Max[int64](tc.input.([]int64)...)
			case float64:
				max, ok = Max[float64](tc.input.([]float64)...)
			default:
				t.Errorf("unexpected type: %T", tc.expected)
			}
			if !ok {
				t.Errorf("expected true, got false")
			}
			if max != tc.expected {
				t.Errorf("expected %v, got %v", tc.expected, max)
			}
		})
	}
}

