package sandbox

import (
	"testing"
)

func TestGroupParity(t *testing.T) {
	testCases := []struct {
		name     string
		input    []int
		expected map[string][]int
	}{
		{
			name:     "empty slice",
			input:    []int{},
			expected: map[string][]int{"even": {}, "odd": {}},
		},
		{
			name:     "single even number",
			input:    []int{2},
			expected: map[string][]int{"even": {2}, "odd": {}},
		},
		{
			name:     "single odd number",
			input:    []int{3},
			expected: map[string][]int{"even": {}, "odd": {3}},
		},
		{
			name:     "mixed numbers",
			input:    []int{1, 2, 3, 4, 5},
			expected: map[string][]int{"even": {2, 4}, "odd": {1, 3, 5}},
		},
		{
			name:     "all even numbers",
			input:    []int{2, 4, 6, 8},
			expected: map[string][]int{"even": {2, 4, 6, 8}, "odd": {}},
		},
		{
			name:     "all odd numbers",
			input:    []int{1, 3, 5, 7},
			expected: map[string][]int{"even": {}, "odd": {1, 3, 5, 7}},
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := GroupParity(tc.input)
			if !equalMaps(result, tc.expected) {
				t.Errorf("GroupParity(%v) = %v; want %v", tc.input, result, tc.expected)
			}
		})
	}
}

func equalMaps(a, b map[string][]int) bool {
	if len(a) != len(b) {
		return false
	}
	for key, value := range a {
		if !equalSlices(value, b[key]) {
			return false
		}
	}
	return true
}

func equalSlices(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

