import (
	"fmt"
	"strings"
	"testing"
	"unicode"
)

// Title upcases the first letter of each whitespace-separated word in the input string.
func Title(s string) string {
	var result []rune
	words := strings.Fields(s)
	for i, word := range words {
		if i > 0 {
			result = append(result, ' ')
		}
		runes := []rune(word)
		runes[0] = unicode.ToUpper(runes[0])
		result = append(result, runes...)
	}
	return string(result)
}

// TestTitle tests the Title function with various cases.
func TestTitle(t *testing.T) {
	testCases := []struct {
		input    string
		expected string
	}{
		{"hello world", "Hello World"},
		{"go is fun", "Go Is Fun"},
		{"", ""},
		{"single", "Single"},
		{"  multiple   spaces ", "  Multiple   Spaces "},
		{"alreadyTitle", "AlreadyTitle"},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result := Title(tc.input)
			if result != tc.expected {
				t.Errorf("Title(%q) = %q; want %q", tc.input, result, tc.expected)
			}
		})
	}
}

