package sandbox

import (
	"errors"
	"fmt"
	"strconv"
	"testing"
)

// SumDigits sums the decimal digits in s, returning an error wrapping strconv via fmt.Errorf %w on a non-digit.
func SumDigits(s string) (int, error) {
	sum := 0
	for _, r := range s {
		digit, err := strconv.Atoi(string(r))
		if err != nil {
			return 0, fmt.Errorf("non-digit character: %w", err)
		}
		sum += digit
	}
	return sum, nil
}

// TestSumDigits tests the SumDigits function with various inputs.
func TestSumDigits(t *testing.T) {
	testCases := []struct {
		input    string
		expected int
		err      error
	}{
		{"12345", 15, nil},
		{"abc", 0, fmt.Errorf("non-digit character: strconv.Atoi: parsing \"a\": invalid syntax")},
		{"1a2b3", 6, nil},
		{"", 0, nil},
		{"123abc", 6, fmt.Errorf("non-digit character: strconv.Atoi: parsing \"a\": invalid syntax")},
	}

	for _, tc := range testCases {
		t.Run(fmt.Sprintf("Input: %s", tc.input), func(t *testing.T) {
			result, err := SumDigits(tc.input)
			if !errors.Is(err, tc.err) {
				t.Errorf("Expected error: %v, got: %v", tc.err, err)
			}
			if result != tc.expected {
				t.Errorf("Expected sum: %d, got: %d", tc.expected, result)
			}
		})
	}
}

