// Merge merges overlapping closed intervals and returns them sorted by start.
func Merge(in [][2]int) [][2]int {
	sort.Slice(in, func(i, j int) bool {
		return in[i][0] < in[j][0]
	})

	var merged [][2]int
	for _, interval := range in {
		if len(merged) == 0 || merged[len(merged)-1][1] < interval[0] {
			merged = append(merged, interval)
		} else {
			merged[len(merged)-1][1] = max(merged[len(merged)-1][1], interval[1])
		}
	}
	return merged
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}

// TestMerge tests the Merge function with various inputs.
func TestMerge(t *testing.T) {
	testCases := []struct {
		input    [][2]int
		expected [][2]int
	}{
		{[][2]int{{1, 3}, {2, 6}, {8, 10}, {15, 18}}, [][2]int{{1, 6}, {8, 10}, {15, 18}}},
		{[][2]int{{1, 4}, {4, 5}}, [][2]int{{1, 5}}},
		{[][2]int{{1, 2}, {3, 4}, {5, 6}}, [][2]int{{1, 2}, {3, 4}, {5, 6}}},
		{[][2]int{{1, 10}, {2, 3}, {4, 5}, {6, 7}, {8, 9}, {10, 12}}, [][2]int{{1, 12}}},
		{[][2]int{}, [][2]int{}},
	}

	for _, tc := range testCases {
		result := Merge(tc.input)
		if !equal(result, tc.expected) {
			t.Errorf("Merge(%v) = %v; want %v", tc.input, result, tc.expected)
		}
	}
}

// equal checks if two slices of intervals are equal.
func equal(a, b [][2]int) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i][0] != b[i][0] || a[i][1] != b[i][1] {
			return false
		}
	}
	return true
