func TestSumHandler(t *testing.T) {
	testCases := []struct {
		name     string
		input    string
		expected string
		status   int
	}{
		{
			name:     "Valid JSON",
			input:    `{"a": 1, "b": 2}`,
			expected: `{"sum": 3}`,
			status:   http.StatusOK,
		},
		{
			name:     "Invalid JSON",
			input:    `{"a": "one", "b": 2}`,
			expected: `{"error": "invalid character 'o' looking for beginning of value"}`,
			status:   http.StatusBadRequest,
		},
		{
			name:     "Missing fields",
			input:    `{"a": 1}`,
			expected: `{"error": "missing field 'b'"}`,
			status:   http.StatusBadRequest,
		},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			req, err := http.NewRequest("POST", "/sum", nil)
			if err != nil {
				t.Fatal(err)
			}
			req.Body = http.NoBody
			if tc.input != "" {
				req.Body = http.NoBody
				json.NewEncoder(req.Body).Encode(map[string]int{"a": 1, "b": 2})
			}

			recorder := httptest.NewRecorder()
			SumHandler(recorder, req)

			if recorder.Code != tc.status {
				t.Errorf("Expected status %d, got %d", tc.status, recorder.Code)
			}

			var response map[string]interface{}
			err = json.Unmarshal(recorder.Body.Bytes(), &response)
			if err != nil {
				t.Errorf("Expected valid JSON response, got error: %v", err)
			}

			expectedResponse := map[string]interface{}{
				"sum": 3,
			}
			if tc.expected != "" {
				expectedResponse = map[string]interface{}{
					"error": tc.expected,
				}
			}

			if !reflect.DeepEqual(response, expectedResponse) {
				t.Errorf("Expected response %v, got %v", expectedResponse, response)
			}
		})
	}
}

