// Filter returns a new slice containing only the elements of s for which keep returns true.
func Filter[T any](s []T, keep func(T) bool) []T {
	var result []T
	for _, v := range s {
		if keep(v) {
			result = append(result, v)
		}
	}
	return result
}

// TestFilter tests the Filter function with various data points.
func TestFilter(t *testing.T) {
	testCases := []struct {
		name     string
		input    []int
		keep     func(int) bool
		expected []int
	}{
		{"empty slice", []int{}, func(i int) bool { return true }, []int{}},
		{"all true", []int{1, 2, 3}, func(i int) bool { return true }, []int{1, 2, 3}},
		{"all false", []int{1, 2, 3}, func(i int) bool { return false }, []int{}},
		{"mixed", []int{1, 2, 3, 4}, func(i int) bool { return i%2 == 0 }, []int{2, 4}},
		{"negative numbers", []int{-1, -2, -3}, func(i int) bool { return i > 0 }, []int{}},
		{"mixed types", []interface{}{"a", 2, "b", 3}, func(i interface{}) bool { _, ok := i.(int); return ok }, []interface{}{2, 3}},
	}

	for _, tc := range testCases {
		t.Run(tc.name, func(t *testing.T) {
			result := Filter(tc.input, tc.keep)
			if !slicesEqual(result, tc.expected) {
				t.Errorf("Filter(%v, %v) = %v; want %v", tc.input, tc.keep, result, tc.expected)
			}
		})
	}
}

// slicesEqual checks if two slices are equal.
func slicesEqual[T comparable](a, b []T) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

