func CountUntil(ctx context.Context, ch <-chan int) int {
	count := 0
	for {
		select {
		case <-ctx.Done():
			return count
		case num, ok := <-ch:
			if !ok {
				return count
			}
			count++
		}
	}
}

func TestCountUntil(t *testing.T) {
	ch := make(chan int)
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	go func() {
		time.Sleep(50 * time.Millisecond)
		ch <- 1
		time.Sleep(50 * time.Millisecond)
		ch <- 2
		close(ch)
	}()

	count := CountUntil(ctx, ch)
	if count != 2 {
		t.Errorf("Expected 2, got %d", count)
	}
}

