import (
	"net/http"
	"net/url"
	"testing"
)

// Chain applies middlewares to an http.Handler, with the first middleware in the list being the outermost.
func Chain(h http.Handler, mws ...func(http.Handler) http.Handler) http.Handler {
	for i := len(mws) - 1; i >= 0; i-- {
		h = mws[i](h)
	}
	return h
}

// TestChain tests the Chain function with a simple handler and multiple middlewares.
func TestChain(t *testing.T) {
	// Define a simple handler
	handler := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Write([]byte("Hello, World!"))
	})

	// Define middlewares
	middleware1 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 1: "))
			next.ServeHTTP(w, r)
		})
	}

	middleware2 := func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Write([]byte("Middleware 2: "))
			next.ServeHTTP(w, r)
		})
	}

	// Chain the handler with the middlewares
	chainedHandler := Chain(handler, middleware1, middleware2)

	// Create a mock ResponseWriter to capture the response
	var response []byte
	mockWriter := http.ResponseWriterFunc(func(w http.ResponseWriter, r *http.Request) {
		response = append(response, w.Header().Get("Content-Type")...)
		response = append(response, w.Header().Get("Content-Length")...)
		response = append(response, w.Header().Get("X-Custom-Header")...)
		response = append(response, w.Header().Get("X-Another-Header")...)
		w.Write([]byte("Response Body"))
	})

	// Create a mock Request
	req := &http.Request{
		Method: "GET",
		URL:    &url.URL{Path: "/"},
	}

	// Call the chained handler
	chainedHandler.ServeHTTP(mockWriter, req)

	// Check the response
	expectedResponse := "Middleware 1: Middleware 2: Hello, World!"
	if string(response) != expectedResponse {
		t.Errorf("Expected response %q, but got %q", expectedResponse, string(response))
	}
}
